// Super Admin initialization and management

import { auth } from '../providers/index.js';
import { config } from '../config.js';

const SUPER_ADMIN_STORAGE_KEY = 'bmms_super_admin_initialized';

/**
 * Check if super admin account exists in Appwrite
 * This function does NOT sign in/out to avoid triggering auth state changes
 * Instead, it checks localStorage for initialization flag
 * @returns {{ exists: boolean, passwordMatch: boolean, needsSync?: boolean }}
 */
export async function checkSuperAdminExists() {
    const superEmail = getSuperAdminEmail();
    if (!superEmail) return { exists: false, passwordMatch: false };

    // Check if we've initialized before
    const wasInitialized = localStorage.getItem(SUPER_ADMIN_STORAGE_KEY) === 'true';

    if (wasInitialized) {
        // Account was initialized before, assume it exists
        // The actual login attempt will verify if password matches
        return { exists: true, passwordMatch: true };
    }

    // Not initialized yet - account doesn't exist
    return { exists: false, passwordMatch: false };
}

/**
 * Try to login super admin, returns result indicating if password matches
 * This is the actual login attempt that will be used for authentication
 * @returns {{ success: boolean, user?: any, needsSync?: boolean, error?: string }}
 */
export async function tryLoginSuperAdmin() {
    const superEmail = getSuperAdminEmail();
    const superPassword = config.SUPER_ADMIN_PASSWORD;

    if (!superEmail || !superPassword) {
        return { success: false, error: 'Super admin credentials not configured' };
    }

    try {
        const { data, error } = await auth.signIn(superEmail, superPassword);

        if (error) {
            // Password mismatch - account exists but wrong password
            if (error.message?.includes('Invalid credentials') || error.code === 401) {
                return { success: false, needsSync: true, error: '密码不匹配' };
            }
            return { success: false, error: error.message };
        }

        if (data?.user) {
            // Mark as initialized
            localStorage.setItem(SUPER_ADMIN_STORAGE_KEY, 'true');
            return { success: true, user: data.user };
        }

        return { success: false, error: '登录失败' };
    } catch (error) {
        if (error.message?.includes('Invalid credentials') || error.code === 401) {
            return { success: false, needsSync: true, error: '密码不匹配' };
        }
        return { success: false, error: error.message };
    }
}

/**
 * Sync super admin password from environment variable to Appwrite
 * This uses the API Key or Cloud Function to update the password
 * @returns {{ success: boolean, error?: string }}
 */
export async function syncSuperAdminPassword() {
    const superEmail = getSuperAdminEmail();
    const newPassword = config.SUPER_ADMIN_PASSWORD;
    const endpoint = config.APPWRITE_URL;
    const projectId = config.APPWRITE_PROJECT_ID;
    const apiKey = config.APPWRITE_API_KEY;
    const mode = config.APPWRITE_PASSWORD_MODE || 'api_key';
    const functionId = config.APPWRITE_FUNCTION_USER_MANAGEMENT;

    if (!superEmail || !newPassword) {
        return { success: false, error: '超管凭据未配置' };
    }

    console.log('[syncSuperAdminPassword] Attempting to sync password...');

    try {
        // First, we need to get the user ID
        // We'll fetch user by email using the API Key
        const userId = await findUserIdByEmail(superEmail, endpoint, projectId, apiKey);

        if (!userId) {
            return { success: false, error: '无法找到超管用户，可能需要删除后重新创建' };
        }

        console.log('[syncSuperAdminPassword] Found user ID:', userId);

        // Update password using configured mode
        if (mode === 'function' && functionId) {
            return await syncPasswordViaFunction(userId, newPassword, endpoint, projectId, functionId);
        } else if (apiKey) {
            return await syncPasswordViaApiKey(userId, newPassword, endpoint, projectId, apiKey);
        } else {
            return {
                success: false,
                error: '无法同步密码：未配置 APPWRITE_API_KEY 或 APPWRITE_FUNCTION_USER_MANAGEMENT。请在 Appwrite Console 中手动更新密码，或删除超管账户后重新登录。'
            };
        }
    } catch (error) {
        console.error('[syncSuperAdminPassword] Error:', error);
        return { success: false, error: error.message || '同步密码失败' };
    }
}

/**
 * Find user ID by email using Appwrite API
 */
async function findUserIdByEmail(email, endpoint, projectId, apiKey) {
    if (!apiKey) {
        console.warn('[findUserIdByEmail] No API key, cannot lookup user');
        return null;
    }

    try {
        const response = await fetch(`${endpoint}/users?queries[]=${encodeURIComponent(`equal("email", ["${email}"])`)}`, {
            method: 'GET',
            headers: {
                'Content-Type': 'application/json',
                'X-Appwrite-Project': projectId,
                'X-Appwrite-Key': apiKey
            }
        });

        if (!response.ok) {
            console.error('[findUserIdByEmail] Failed to lookup user:', response.status);
            return null;
        }

        const data = await response.json();
        if (data.users && data.users.length > 0) {
            return data.users[0].$id;
        }
        return null;
    } catch (error) {
        console.error('[findUserIdByEmail] Error:', error);
        return null;
    }
}

/**
 * Sync password using API Key
 */
async function syncPasswordViaApiKey(userId, newPassword, endpoint, projectId, apiKey) {
    try {
        const response = await fetch(`${endpoint}/users/${userId}/password`, {
            method: 'PATCH',
            headers: {
                'Content-Type': 'application/json',
                'X-Appwrite-Project': projectId,
                'X-Appwrite-Key': apiKey
            },
            body: JSON.stringify({ password: newPassword })
        });

        if (!response.ok) {
            const errorData = await response.json().catch(() => ({}));
            throw new Error(errorData.message || `同步密码失败 (${response.status})`);
        }

        console.log('[syncPasswordViaApiKey] Password synced successfully');
        return { success: true };
    } catch (error) {
        console.error('[syncPasswordViaApiKey] Error:', error);
        return { success: false, error: error.message };
    }
}

/**
 * Sync password using Cloud Function
 */
async function syncPasswordViaFunction(userId, newPassword, endpoint, projectId, functionId) {
    try {
        const response = await fetch(`${endpoint}/functions/${functionId}/executions`, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'X-Appwrite-Project': projectId
            },
            body: JSON.stringify({
                body: JSON.stringify({ userId, newPassword }),
                async: false
            })
        });

        if (!response.ok) {
            const errorData = await response.json().catch(() => ({}));
            throw new Error(errorData.message || `调用 Function 失败 (${response.status})`);
        }

        const execution = await response.json();

        if (execution.status === 'completed') {
            const result = JSON.parse(execution.responseBody || '{}');
            if (result.success) {
                console.log('[syncPasswordViaFunction] Password synced successfully');
                return { success: true };
            } else {
                throw new Error(result.message || '同步密码失败');
            }
        } else {
            throw new Error(`Function 执行失败: ${execution.status}`);
        }
    } catch (error) {
        console.error('[syncPasswordViaFunction] Error:', error);
        return { success: false, error: error.message };
    }
}

/**
 * Create super admin account in Appwrite
 */
export async function initializeSuperAdmin() {
    const superUsername = config.SUPER_ADMIN_USERNAME;
    const superPassword = config.SUPER_ADMIN_PASSWORD;
    const superEmail = getSuperAdminEmail();

    if (!superUsername || !superPassword) {
        throw new Error('Super admin credentials not configured in environment');
    }

    try {
        // Create Appwrite auth account
        const { data: authData, error: authError } = await auth.signUp(
            superEmail,
            superPassword,
            { username: superUsername }
        );

        if (authError) {
            // If user already exists, that's ok
            if (authError.message?.includes('already')) {
                console.log('Super admin account already exists');
                return { success: true, alreadyExists: true };
            }
            throw authError;
        }

        // Mark as initialized
        localStorage.setItem(SUPER_ADMIN_STORAGE_KEY, 'true');

        return { success: true, user: authData.user };
    } catch (error) {
        console.error('Failed to initialize super admin:', error);
        throw error;
    }
}

/**
 * Login as super admin using Appwrite auth
 */
export async function loginSuperAdmin() {
    const superEmail = getSuperAdminEmail();
    const superPassword = config.SUPER_ADMIN_PASSWORD;

    if (!superEmail || !superPassword) {
        throw new Error('Super admin credentials not configured');
    }

    try {
        const { data, error } = await auth.signIn(superEmail, superPassword);

        if (error) {
            // If password doesn't match, might have been changed in .env
            if (error.message?.includes('Invalid credentials') || error.code === 401) {
                throw new Error('Super admin password mismatch. Please update password in Appwrite Console or delete the account to reinitialize.');
            }
            throw error;
        }

        return { success: true, user: data.user };
    } catch (error) {
        console.error('Super admin login failed:', error);
        throw error;
    }
}

/**
 * Check if we should auto-initialize super admin
 */
export function shouldInitializeSuperAdmin() {
    return !localStorage.getItem(SUPER_ADMIN_STORAGE_KEY);
}

/**
 * Get super admin email from username
 */
function getSuperAdminEmail() {
    const username = config.SUPER_ADMIN_USERNAME;
    if (!username) return null;

    // Use a special domain for super admin
    return `${username}@bmms.superadmin.local`;
}

/**
 * Verify if credentials match super admin
 */
export function verifySuperAdminCredentials(username, password) {
    return (
        username === config.SUPER_ADMIN_USERNAME &&
        password === config.SUPER_ADMIN_PASSWORD
    );
}

