<script>
  import { onMount } from 'svelte';
  import { authStore, uiStore } from '../stores/index.js';
  import { usersApi } from '../services/database.js';
  import { 
    ROLES, 
    getRoleLabel, 
    canManageUsers, 
    getCreatableRoles, 
    getManageableRoles,
    DEFAULT_ROLE
  } from '../constants/roles.js';

  let users = [];
  let isLoading = true;
  let role = null;
  let showCreateModal = false;
  let isCreating = false;
  
  // Change password modal state
  let showPasswordModal = false;
  let isUpdatingPassword = false;
  let selectedUser = null;
  let newPassword = '';
  let passwordModalMode = 'change'; // 'change' 或 'reset'
  
  // Password result modal state (重置密码结果弹窗)
  let showPasswordResultModal = false;
  let generatedPasswordResult = '';
  let resetTargetUsername = '';

  // Create user form state
  let newUser = {
    email: '',
    username: '',
    password: '',
    role: ''  // 默认为空，强制用户选择
  };

  authStore.subscribe(state => {
    role = state.role;
  });

  // 可创建的角色列表
  $: creatableRoles = getCreatableRoles(role);
  // 可管理的角色列表
  $: manageableRoles = getManageableRoles(role);

  onMount(async () => {
    // Allow both super_admin and admin to access user management
    if (!canManageUsers(role)) {
      uiStore.showNotification('无权访问用户管理', 'error');
      return;
    }
    await loadUsers();
  });

  async function loadUsers() {
    isLoading = true;
    const result = await usersApi.list();
    let allUsers = result.data || [];
    
    // Filter users based on role - only show users that current role can manage
    if (role === ROLES.ADMIN) {
      // Admin can only see in_operator, out_operator, observer users
      users = allUsers.filter(u => manageableRoles.includes(u.role));
    } else if (role === ROLES.SUPER_ADMIN) {
      // Super admin can see all users except super_admin
      users = allUsers.filter(u => u.role !== ROLES.SUPER_ADMIN);
    } else {
      users = [];
    }
    
    isLoading = false;
  }

  async function updateRole(userId, newRole) {
    // 验证是否有权限设置该角色
    if (!manageableRoles.includes(newRole)) {
      uiStore.showNotification('无权设置此角色', 'error');
      return;
    }

    uiStore.showLoading('更新角色中...');
    try {
      await usersApi.updateRole(userId, newRole);
      uiStore.showNotification('角色更新成功', 'success');
      loadUsers();
    } catch (error) {
      uiStore.showNotification('更新失败', 'error');
    } finally {
      uiStore.hideLoading();
    }
  }

  async function handleCreateUser() {
    if (!newUser.email || !newUser.username || !newUser.password) {
      uiStore.showNotification('请填写所有必填字段', 'error');
      return;
    }

    if (newUser.password.length < 8) {
      uiStore.showNotification('密码至少需要8个字符', 'error');
      return;
    }

    // 验证是否选择了角色
    if (!newUser.role) {
      uiStore.showNotification('请选择用户角色', 'error');
      return;
    }

    // 验证是否有权限创建该角色
    if (!creatableRoles.includes(newUser.role)) {
      uiStore.showNotification('无权创建此角色的用户', 'error');
      return;
    }

    isCreating = true;
    uiStore.showLoading('创建用户中...');
    try {
      const result = await usersApi.create(
        newUser.email,
        newUser.username,
        newUser.password,
        newUser.role
      );

      if (result.error) {
        throw result.error;
      }

      uiStore.showNotification('用户创建成功', 'success');
      showCreateModal = false;
      resetForm();
      loadUsers();
    } catch (error) {
      console.error('Create user error:', error);
      const errorMsg = error.message || '创建用户失败';
      uiStore.showNotification(errorMsg, 'error');
    } finally {
      isCreating = false;
      uiStore.hideLoading();
    }
  }

  async function handleDeleteUser(userId, username, userRole) {
    // 验证是否有权限删除该角色的用户
    if (!manageableRoles.includes(userRole)) {
      uiStore.showNotification('无权删除此用户', 'error');
      return;
    }

    if (!confirm(`确定要删除用户 "${username}" 吗？此操作不可撤销。`)) {
      return;
    }

    uiStore.showLoading('删除用户中...');
    try {
      const result = await usersApi.delete(userId);
      if (result.error) {
        throw result.error;
      }
      uiStore.showNotification('用户已删除', 'success');
      loadUsers();
    } catch (error) {
      console.error('Delete user error:', error);
      uiStore.showNotification('删除失败', 'error');
    } finally {
      uiStore.hideLoading();
    }
  }

  function openPasswordModal(user, mode = 'change') {
    selectedUser = user;
    newPassword = '';
    passwordModalMode = mode;
    showPasswordModal = true;
  }

  // 生成随机密码（用于重置密码）
  function generateRandomPassword() {
    const chars = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%';
    let password = '';
    for (let i = 0; i < 12; i++) {
      password += chars.charAt(Math.floor(Math.random() * chars.length));
    }
    return password;
  }

  async function handleResetPassword() {
    // 验证是否有权限
    if (!manageableRoles.includes(selectedUser.role)) {
      uiStore.showNotification('无权重置此用户的密码', 'error');
      return;
    }

    const generatedPassword = generateRandomPassword();
    
    isUpdatingPassword = true;
    uiStore.showLoading('重置密码中...');
    try {
      const result = await usersApi.updatePassword(selectedUser.$id, generatedPassword);
      if (result.error) {
        throw result.error;
      }
      // 关闭重置密码确认弹窗，显示密码结果弹窗
      resetTargetUsername = selectedUser.username;
      generatedPasswordResult = generatedPassword;
      showPasswordModal = false;
      selectedUser = null;
      showPasswordResultModal = true;
    } catch (error) {
      console.error('Reset password error:', error);
      const errorMsg = error.message || '重置密码失败';
      uiStore.showNotification(errorMsg, 'error');
    } finally {
      isUpdatingPassword = false;
      uiStore.hideLoading();
    }
  }

  async function copyPasswordToClipboard() {
    try {
      await navigator.clipboard.writeText(generatedPasswordResult);
      uiStore.showNotification('密码已复制到剪贴板', 'success');
    } catch (err) {
      // 如果剪贴板 API 不可用，选中文本
      uiStore.showNotification('请手动复制密码', 'warning');
    }
  }

  function closePasswordResultModal() {
    showPasswordResultModal = false;
    generatedPasswordResult = '';
    resetTargetUsername = '';
  }

  async function handleUpdatePassword() {
    if (!newPassword) {
      uiStore.showNotification('请输入新密码', 'error');
      return;
    }

    if (newPassword.length < 8) {
      uiStore.showNotification('密码至少需要8个字符', 'error');
      return;
    }

    // 验证是否有权限修改该用户的密码（仅super_admin可以修改密码）
    if (role !== ROLES.SUPER_ADMIN) {
      uiStore.showNotification('只有超级管理员可以修改密码', 'error');
      return;
    }

    if (!manageableRoles.includes(selectedUser.role)) {
      uiStore.showNotification('无权修改此用户的密码', 'error');
      return;
    }

    isUpdatingPassword = true;
    uiStore.showLoading('修改密码中...');
    try {
      const result = await usersApi.updatePassword(selectedUser.$id, newPassword);
      if (result.error) {
        throw result.error;
      }
      uiStore.showNotification('密码修改成功', 'success');
      showPasswordModal = false;
      newPassword = '';
      selectedUser = null;
    } catch (error) {
      console.error('Update password error:', error);
      const errorMsg = error.message || '修改密码失败';
      uiStore.showNotification(errorMsg, 'error');
    } finally {
      isUpdatingPassword = false;
      uiStore.hideLoading();
    }
  }

  function resetForm() {
    newUser = {
      email: '',
      username: '',
      password: '',
      role: ''  // 重置为空，强制用户选择
    };
  }
</script>

<div class="user-management">
  <div class="page-header">
    <div class="header-content">
      <div>
        <h1>用户管理</h1>
        <p>{role === ROLES.SUPER_ADMIN ? '管理系统用户和分配角色权限' : '管理用户'}</p>
      </div>
      {#if canManageUsers(role)}
        <button class="btn-create" on:click={() => showCreateModal = true}>
          + 新建用户
        </button>
      {/if}
    </div>
  </div>

  {#if !canManageUsers(role)}
    <div class="access-denied">
      <div class="icon">🔒</div>
      <h2>权限不足</h2>
      <p>只有超级管理员或管理员才能访问用户管理功能</p>
    </div>
  {:else if isLoading}
    <div class="loading">
      <div class="spinner"></div>
      <p>加载用户列表...</p>
    </div>
  {:else}
    <div class="users-table-container">
      <table class="users-table">
        <thead>
          <tr>
            <th>用户名</th>
            <th>邮箱</th>
            <th>当前角色</th>
            <th>创建时间</th>
            <th>操作</th>
          </tr>
        </thead>
        <tbody>
          {#each users as user (user.$id)}
            <tr>
              <td>{user.username || '--'}</td>
              <td>{user.email || '--'}</td>
              <td>
                <span class="role-badge" 
                  class:admin={user.role === ROLES.ADMIN} 
                  class:in-operator={user.role === ROLES.IN_OPERATOR}
                  class:out-operator={user.role === ROLES.OUT_OPERATOR}
                  class:observer={user.role === ROLES.OBSERVER}>
                  {getRoleLabel(user.role)}
                </span>
              </td>
              <td>{user.created_at ? new Date(user.created_at).toLocaleDateString() : '--'}</td>
              <td>
                <div class="action-buttons">
                  {#if role === ROLES.SUPER_ADMIN || manageableRoles.includes(user.role)}
                    <select 
                      value={user.role || ROLES.OBSERVER}
                      on:change={(e) => updateRole(user.$id, e.target.value)}
                    >
                      {#each manageableRoles as r}
                        <option value={r}>{getRoleLabel(r)}</option>
                      {/each}
                    </select>
                    {#if role === ROLES.SUPER_ADMIN}
                      <button 
                        class="btn-password"
                        on:click={() => openPasswordModal(user, 'change')}
                        title="修改密码"
                      >
                        🔑
                      </button>
                    {/if}
                    <button 
                      class="btn-reset"
                      on:click={() => openPasswordModal(user, 'reset')}
                      title="重置密码"
                    >
                      🔄
                    </button>
                    <button 
                      class="btn-delete"
                      on:click={() => handleDeleteUser(user.$id, user.username, user.role)}
                      title="删除用户"
                    >
                      🗑️
                    </button>
                  {:else}
                    <span class="role-display">仅查看</span>
                  {/if}
                </div>
              </td>
            </tr>
          {:else}
            <tr>
              <td colspan="5" class="empty-row">暂无用户数据</td>
            </tr>
          {/each}
        </tbody>
      </table>
    </div>

    <div class="info-card">
      <h3>角色说明</h3>
      <ul>
        <li><strong>管理员</strong>：可创建项目、分类，管理所有材料数据和用户</li>
        <li><strong>入库操作员</strong>：只能录入和查看材料入库数据</li>
        <li><strong>出库操作员</strong>：只能录入和查看材料出库数据</li>
        <li><strong>观察员</strong>：只能查看数据，无任何操作权限</li>
      </ul>
    </div>
  {/if}
</div>

<!-- Create User Modal -->
{#if showCreateModal}
  <div class="modal-overlay" on:click={() => showCreateModal = false} on:keydown={(e) => e.key === 'Escape' && (showCreateModal = false)} role="button" tabindex="-1">
    <div class="modal" on:click|stopPropagation>
      <div class="modal-header">
        <h2>创建新用户</h2>
        <button class="close-btn" on:click={() => showCreateModal = false}>×</button>
      </div>
      <div class="modal-body">
        <form on:submit|preventDefault={handleCreateUser}>
          <div class="form-group">
            <label for="email">邮箱 *</label>
            <input
              id="email"
              type="email"
              bind:value={newUser.email}
              placeholder="user@example.com"
              required
              disabled={isCreating}
            />
          </div>

          <div class="form-group">
            <label for="username">用户名 *</label>
            <input
              id="username"
              type="text"
              bind:value={newUser.username}
              placeholder="请输入用户名"
              required
              disabled={isCreating}
            />
          </div>

          <div class="form-group">
            <label for="password">密码 *</label>
            <input
              id="password"
              type="password"
              bind:value={newUser.password}
              placeholder="至少8个字符"
              required
              minlength="8"
              disabled={isCreating}
            />
            <small>密码长度至少为8个字符</small>
          </div>

          <div class="form-group">
            <label for="role">角色 *</label>
            <select
              id="role"
              bind:value={newUser.role}
              disabled={isCreating}
              required
            >
              <option value="" disabled>请选择角色</option>
              {#each creatableRoles as r}
                <option value={r}>{getRoleLabel(r)}</option>
              {/each}
            </select>
            <small>选择用户的角色权限</small>
          </div>

          <div class="modal-actions">
            <button type="submit" class="btn-primary" disabled={isCreating}>
              {isCreating ? '创建中...' : '创建用户'}
            </button>
            <button 
              type="button" 
              class="btn-secondary" 
              on:click={() => showCreateModal = false}
              disabled={isCreating}
            >
              取消
            </button>
          </div>
        </form>
      </div>
    </div>
  </div>
{/if}

<!-- Change/Reset Password Modal -->
{#if showPasswordModal}
  <div class="modal-overlay" on:click={() => showPasswordModal = false} on:keydown={(e) => e.key === 'Escape' && (showPasswordModal = false)} role="button" tabindex="-1">
    <div class="modal" on:click|stopPropagation>
      <div class="modal-header">
        <h2>{passwordModalMode === 'reset' ? '重置密码' : '修改密码'}</h2>
        <button class="close-btn" on:click={() => showPasswordModal = false}>×</button>
      </div>
      <div class="modal-body">
        <div class="user-info">
          <p><strong>用户名:</strong> {selectedUser?.username || '--'}</p>
          <p><strong>邮箱:</strong> {selectedUser?.email || '--'}</p>
        </div>
        
        {#if passwordModalMode === 'reset'}
          <!-- 重置密码模式：确认后自动生成随机密码 -->
          <div class="reset-info">
            <p>⚠️ 点击确认后，系统将为该用户生成一个随机密码。</p>
            <p>新密码会显示在通知中，请及时通知用户。</p>
          </div>
          <div class="modal-actions">
            <button type="button" class="btn-warning" on:click={handleResetPassword} disabled={isUpdatingPassword}>
              {isUpdatingPassword ? '重置中...' : '确认重置'}
            </button>
            <button 
              type="button" 
              class="btn-secondary" 
              on:click={() => showPasswordModal = false}
              disabled={isUpdatingPassword}
            >
              取消
            </button>
          </div>
        {:else}
          <!-- 修改密码模式：需要输入新密码 -->
          <form on:submit|preventDefault={handleUpdatePassword}>
            <div class="form-group">
              <label for="newPassword">新密码 *</label>
              <input
                id="newPassword"
                type="password"
                bind:value={newPassword}
                placeholder="请输入新密码（至少8个字符）"
                required
                minlength="8"
                disabled={isUpdatingPassword}
              />
              <small>密码长度至少为8个字符</small>
            </div>

            <div class="modal-actions">
              <button type="submit" class="btn-primary" disabled={isUpdatingPassword}>
                {isUpdatingPassword ? '修改中...' : '确认修改'}
              </button>
              <button 
                type="button" 
                class="btn-secondary" 
                on:click={() => showPasswordModal = false}
                disabled={isUpdatingPassword}
              >
                取消
              </button>
            </div>
          </form>
        {/if}
      </div>
    </div>
  </div>
{/if}

<!-- Password Result Modal (重置密码结果弹窗) -->
{#if showPasswordResultModal}
  <div class="modal-overlay" role="dialog" tabindex="-1">
    <div class="modal password-result-modal">
      <div class="modal-header result-header">
        <h2>🔐 密码重置成功</h2>
      </div>
      <div class="modal-body">
        <div class="warning-box">
          <div class="warning-icon">⚠️</div>
          <div class="warning-text">
            <strong>重要提醒</strong>
            <p>此密码只会显示一次！请务必复制保存后再关闭此窗口。</p>
          </div>
        </div>
        
        <div class="password-result-box">
          <div class="password-label">用户 <strong>{resetTargetUsername}</strong> 的新密码：</div>
          <div class="password-display">
            <code class="password-text">{generatedPasswordResult}</code>
            <button class="btn-copy" on:click={copyPasswordToClipboard} title="复制密码">
              📋 复制
            </button>
          </div>
        </div>

        <div class="reminder-text">
          <p>✅ 请将此密码通过安全渠道告知用户</p>
          <p>✅ 建议用户登录后立即修改密码</p>
        </div>

        <div class="modal-actions">
          <button type="button" class="btn-primary" on:click={closePasswordResultModal}>
            我已复制密码，关闭窗口
          </button>
        </div>
      </div>
    </div>
  </div>
{/if}

